106	  protected HoodieRollbackRequest createRollbackRequestForCreateAndMerge(String fileId,
107	                                                                         String partitionPath,
108	                                                                         StoragePath filePath,
109	                                                                         HoodieInstant instantToRollback) {
110	    if (table.version().greaterThanOrEquals(HoodieTableVersion.EIGHT)) {
111	      return new HoodieRollbackRequest(partitionPath, fileId, instantToRollback.requestedTime(),
112	          Collections.singletonList(filePath.toString()), Collections.emptyMap());
113	    } else {
114	      String baseInstantTime = null;
115	      if (FSUtils.isBaseFile(filePath)) {
116	        HoodieBaseFile baseFileToDelete = new HoodieBaseFile(filePath.toString());
117	        fileId = baseFileToDelete.getFileId();
118	        baseInstantTime = baseFileToDelete.getCommitTime();
119	      } else if (FSUtils.isLogFile(filePath)) {
120	        throw new HoodieRollbackException("Log files should have only APPEND as IOTypes " + filePath);
121	      }
122	      Objects.requireNonNull(fileId, "Cannot find valid fileId from path: " + filePath);
123	      Objects.requireNonNull(baseInstantTime, "Cannot find valid base instant from path: " + filePath);
124	      return new HoodieRollbackRequest(partitionPath, fileId, baseInstantTime,
125	          Collections.singletonList(filePath.toString()),
126	          Collections.emptyMap());
127	    }
128	  }
